@Test
public void noBatching() throws Exception {
    // This test uses a different mock/fake because it explicitly does not want to populate the
    // Spanner schema.
    FakeServiceFactory fakeServiceFactory = new FakeServiceFactory();
    ReadOnlyTransaction tx = mock(ReadOnlyTransaction.class);
    when(fakeServiceFactory.mockDatabaseClient().readOnlyTransaction()).thenReturn(tx);
    // Capture batches sent to writeAtLeastOnceWithOptions.
    when(fakeServiceFactory.mockDatabaseClient().writeAtLeastOnceWithOptions(mutationBatchesCaptor.capture(), optionsCaptor.capture())).thenReturn(null);
    PCollection<MutationGroup> mutations = pipeline.apply(Create.of(buildMutationGroup(buildUpsertMutation(1L)), buildMutationGroup(buildUpsertMutation(2L))));
    mutations.apply(SpannerIO.write().withSpannerConfig(SPANNER_CONFIG).withServiceFactory(fakeServiceFactory).withBatchSizeBytes(1).grouped());
    pipeline.run();
    verify(fakeServiceFactory.mockDatabaseClient(), times(1)).writeAtLeastOnceWithOptions(mutationsInNoOrder(buildMutationBatch(buildUpsertMutation(1L))), any(ReadQueryUpdateTransactionOption.class));
    verify(fakeServiceFactory.mockDatabaseClient(), times(1)).writeAtLeastOnceWithOptions(mutationsInNoOrder(buildMutationBatch(buildUpsertMutation(2L))), any(ReadQueryUpdateTransactionOption.class));
    // If no batching then the DB schema is never read.
    verify(tx, never()).executeQuery(any());
    verifyTableWriteRequestMetricWasSet(SPANNER_CONFIG, TABLE_NAME, "ok", 2);
}

