    testStub.injectWorkerMetadata(freshEndpoints);
    List<WorkerMetadataResponse.Endpoint> staleDirectPathEndpoints = Lists.newArrayList(WorkerMetadataResponse.Endpoint.newBuilder().setDirectEndpoint("staleWindmillEndpoint").build());
    Map<String, WorkerMetadataResponse.Endpoint> staleGlobalDataEndpoints = new HashMap<>();
