    testStub.injectWorkerMetadata(WorkerMetadataResponse.newBuilder().setMetadataVersion(1).addAllWorkEndpoints(staleDirectPathEndpoints).putAllGlobalDataEndpoints(staleGlobalDataEndpoints).build());
