@Test
public void testObserverOneEndpointReturns() {
    ExpansionServiceClient expansionServiceClient = Mockito.mock(ExpansionServiceClient.class);
    Mockito.when(clientFactory.getExpansionServiceClient(Mockito.any())).thenReturn(expansionServiceClient);
    Mockito.when(expansionServiceClient.discover(Mockito.any())).thenReturn(DiscoverSchemaTransformResponse.newBuilder().putSchemaTransformConfigs("schematransform_key_1", SchemaTransformConfig.newBuilder().build()).build()).thenReturn(DiscoverSchemaTransformResponse.newBuilder().setError("discovery error 1").build());
    DiscoverSchemaTransformRequest request = DiscoverSchemaTransformRequest.newBuilder().build();
    StreamObserver<DiscoverSchemaTransformResponse> responseObserver = Mockito.mock(StreamObserver.class);
    expansionService.discoverSchemaTransform(request, responseObserver);
    Mockito.verify(expansionServiceClient, Mockito.times(2)).discover(request);
    ArgumentCaptor<DiscoverSchemaTransformResponse> discoverResponseCapture = ArgumentCaptor.forClass(DiscoverSchemaTransformResponse.class);
    Mockito.verify(responseObserver).onNext(discoverResponseCapture.capture());
    assertEquals(1, discoverResponseCapture.getValue().getSchemaTransformConfigsCount());
    assertTrue(discoverResponseCapture.getValue().getSchemaTransformConfigsMap().containsKey("schematransform_key_1"));
}

