public void testGatherBundleAndSortFn_flushOversizedBundle() throws Exception {
    // Setup class to bundle every 6 rows and create batches of 2.
    GatherSortCreateBatchesFn testFn = new GatherSortCreateBatchesFn(// batch bytes
    10000000, // batch up to 14 mutated cells.
    100, // batch rows
    2, // groupingFactor
    3, null);
    GatherSortCreateBatchesFn.ProcessContext mockProcessContext = Mockito.mock(ProcessContext.class);
    GatherSortCreateBatchesFn.FinishBundleContext mockFinishBundleContext = Mockito.mock(FinishBundleContext.class);
    when(mockProcessContext.sideInput(any())).thenReturn(getSchema());
    OutputReceiver<Iterable<MutationGroup>> mockOutputReceiver = mock(OutputReceiver.class);
    // Capture the outputs.
    doNothing().when(mockOutputReceiver).output(mutationGroupListCaptor.capture());
    // Capture the outputs.
    doNothing().when(mockFinishBundleContext).output(mutationGroupListCaptor.capture(), any(), any());
    MutationGroup[] mutationGroups = new MutationGroup[] { // Unsorted group of 12 mutations.
    // each mutation is considered 7 cells,
    // should be sorted and output as 2 lists of 5, then 1 list of 2
    // with mutations sorted in order.
    buildMutationGroup(buildUpsertMutation(4L)), buildMutationGroup(buildUpsertMutation(1L)), buildMutationGroup(buildUpsertMutation(7L)), buildMutationGroup(buildUpsertMutation(9L)), buildMutationGroup(buildUpsertMutation(10L)), buildMutationGroup(buildUpsertMutation(11L)), // end group
    buildMutationGroup(buildUpsertMutation(2L)), // end batch
    buildMutationGroup(buildDeleteMutation(8L)), buildMutationGroup(buildUpsertMutation(3L)), // end batch
    buildMutationGroup(buildUpsertMutation(6L)), buildMutationGroup(buildUpsertMutation(5L)) // end bundle, so end group and end batch.
    };
    // Process all elements as one bundle.
    for (MutationGroup m : mutationGroups) {
        when(mockProcessContext.element()).thenReturn(m);
        testFn.processElement(mockProcessContext, mockOutputReceiver);
    }
    testFn.finishBundle(mockFinishBundleContext);
    // processElement ouput receiver should have been called 3 times when the 1st group was full.
    verify(mockOutputReceiver, times(3)).output(any());
    // finsihBundleContext output should be called 3 times when the bundle was finished.
    verify(mockFinishBundleContext, times(3)).output(any(), any(), any());
    List<Iterable<MutationGroup>> mgListGroups = mutationGroupListCaptor.getAllValues();
    assertEquals(6, mgListGroups.size());
    // verify contents of 6 sorted groups.
    // first group should be 1,3,4,7,9,11
    assertThat(mgListGroups.get(0), contains(buildMutationGroup(buildUpsertMutation(1L)), buildMutationGroup(buildUpsertMutation(4L))));
    assertThat(mgListGroups.get(1), contains(buildMutationGroup(buildUpsertMutation(7L)), buildMutationGroup(buildUpsertMutation(9L))));
    assertThat(mgListGroups.get(2), contains(buildMutationGroup(buildUpsertMutation(10L)), buildMutationGroup(buildUpsertMutation(11L))));
    // second group at finishBundle should be 2,3,5,6,8
    assertThat(mgListGroups.get(3), contains(buildMutationGroup(buildUpsertMutation(2L)), buildMutationGroup(buildUpsertMutation(3L))));
    assertThat(mgListGroups.get(4), contains(buildMutationGroup(buildUpsertMutation(5L)), buildMutationGroup(buildUpsertMutation(6L))));
    assertThat(mgListGroups.get(5), contains(buildMutationGroup(buildDeleteMutation(8L))));
}

