@Test
public void testBatchableMutationFilterFn_cells() {
    Mutation all = Mutation.delete(TABLE_NAME, KeySet.all());
    Mutation prefix = Mutation.delete(TABLE_NAME, KeySet.prefixRange(Key.of(1L)));
    Mutation range = Mutation.delete(TABLE_NAME, KeySet.range(KeyRange.openOpen(Key.of(1L), Key.newBuilder().build())));
    MutationGroup[] mutationGroups = new MutationGroup[] { buildMutationGroup(buildUpsertMutation(1L)), buildMutationGroup(buildUpsertMutation(2L), buildUpsertMutation(3L)), buildMutationGroup(buildUpsertMutation(2L), buildUpsertMutation(3L), buildUpsertMutation(4L), // not batchable - too big.
    buildUpsertMutation(5L)), buildMutationGroup(buildDeleteMutation(1L)), // not point delete.
    buildMutationGroup(buildDeleteMutation(5L, 6L)), buildMutationGroup(all), buildMutationGroup(prefix), buildMutationGroup(range) };
    BatchableMutationFilterFn testFn = new BatchableMutationFilterFn(null, null, 10000000, 3 * CELLS_PER_KEY, 1000);
    BatchableMutationFilterFn.ProcessContext mockProcessContext = Mockito.mock(ProcessContext.class);
    when(mockProcessContext.sideInput(any())).thenReturn(getSchema());
    // Capture the outputs.
    doNothing().when(mockProcessContext).output(mutationGroupCaptor.capture());
    doNothing().when(mockProcessContext).output(any(), mutationGroupListCaptor.capture());
    // Process all elements.
    for (MutationGroup m : mutationGroups) {
        when(mockProcessContext.element()).thenReturn(m);
        testFn.processElement(mockProcessContext);
    }
    // Verify captured batchable elements.
    assertThat(mutationGroupCaptor.getAllValues(), containsInAnyOrder(buildMutationGroup(buildUpsertMutation(1L)), buildMutationGroup(buildUpsertMutation(2L), buildUpsertMutation(3L)), buildMutationGroup(buildDeleteMutation(1L))));
    // Verify captured unbatchable mutations
    Iterable<MutationGroup> unbatchableMutations = Iterables.concat(mutationGroupListCaptor.getAllValues());
    assertThat(unbatchableMutations, containsInAnyOrder(buildMutationGroup(buildUpsertMutation(2L), buildUpsertMutation(3L), buildUpsertMutation(4L), // not batchable - too big.
    buildUpsertMutation(5L)), // not point delete.
    buildMutationGroup(buildDeleteMutation(5L, 6L)), buildMutationGroup(all), buildMutationGroup(prefix), buildMutationGroup(range)));
}

