            return "blah";
        }

        @Override
        public Object restriction() {
            return "foo";
        }

        @Override
        public OutputReceiver<String> outputReceiver(DoFn<String, String> doFn) {
            return new DoFn.OutputReceiver<String>() {

                private boolean invoked;

                @Override
                public OutputBuilder<String> builder(String value) {
                    return WindowedValues.<String>builder().setValue(value).setTimestamp(mockTimestamp).setWindow(mockWindow).setPaneInfo(PaneInfo.NO_FIRING).setReceiver(windowedValue -> {
                        assertFalse(invoked);
                        invoked = true;
                        assertEquals("foo", windowedValue.getValue());
                    });
                }
            };
        }
    });
