@Test
public void testPollWithIdleTimeout() throws Exception {
    ManuallyTriggeredScheduledExecutorService executor = new ManuallyTriggeredScheduledExecutorService();
    ReaderOutput<WindowedValue<KV<Integer, Integer>>> mockReaderOutput = Mockito.mock(ReaderOutput.class);
    try (FlinkBoundedSourceReader<KV<Integer, Integer>> reader = (FlinkBoundedSourceReader<KV<Integer, Integer>>) createReader(executor, 1)) {
        reader.notifyNoMoreSplits();
        assertEquals(InputStatus.NOTHING_AVAILABLE, reader.pollNext(mockReaderOutput));
        executor.triggerScheduledTasks();
        assertEquals(InputStatus.END_OF_INPUT, reader.pollNext(mockReaderOutput));
    }
}

@Test
public void testPollEmitsMaxWatermark() throws Exception {
    ManuallyTriggeredScheduledExecutorService executor = new ManuallyTriggeredScheduledExecutorService();
    ReaderOutput<WindowedValue<KV<Integer, Integer>>> mockReaderOutput = Mockito.mock(ReaderOutput.class);
    try (FlinkBoundedSourceReader<KV<Integer, Integer>> reader = (FlinkBoundedSourceReader<KV<Integer, Integer>>) createReader(executor, Long.MAX_VALUE)) {
        reader.notifyNoMoreSplits();
        assertEquals(InputStatus.NOTHING_AVAILABLE, reader.pollNext(mockReaderOutput));
        verify(mockReaderOutput).emitWatermark(Watermark.MAX_WATERMARK);
    }
}

